html:
{%- set fel = fel_print_context(doc) -%}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set address = frappe.get_doc("Address", doc.company_address) if doc.company_address else None -%}
<style>
  .fel { font-size: 11px; color: #000; line-height: 1.35; }
  .fel h2 { font-size: 16px; font-weight: 600; margin: 0 0 4px; }
  .fel table { width: 100%; border-collapse: collapse; }
  .fel .lines th, .fel .lines td { border: 1px solid #999; padding: 4px 6px; }
  .fel .lines th { background: #f2f2f2; color: #000; font-weight: 600; text-align: left; }
  .fel .num { text-align: right; white-space: nowrap; }
  .fel .box { border: 1px solid #999; padding: 8px; margin-top: 8px; }
  .fel .warn { border: 2px solid #b00; color: #b00; padding: 8px; margin: 8px 0; font-weight: bold; }
  .fel .void { border: 3px solid #b00; color: #b00; padding: 10px; margin: 8px 0; font-size: 16px; font-weight: bold; text-align: center; }
  .fel .uuid { word-break: break-all; }
  .fel .muted { color: #444; }
  .fel .qr img { width: 120px !important; height: 120px !important; }
</style>
<div class="fel">
  <table>
    <tr>
      <td style="width:58%; vertical-align:top">
        <h2>{{ company.facelec_trade_name or company.company_name }}</h2>
        <div>{{ company.company_name }} &middot; NIT {{ company.nit_face_company or company.tax_id }}</div>
        {%- if address %}
        <div>{{ address.address_line1 }}{% if address.address_line2 %}, {{ address.address_line2 }}{% endif %}</div>
        <div>{{ [address.city, address.state if address.state != address.city else None, address.country if address.country != "Guatemala" else None] | select | join(", ") }}</div>
        {%- endif %}
        {%- if fel.establecimiento %}<div>{{ _("Establecimiento") }} {{ fel.establecimiento.codigo }}{% if fel.establecimiento.nombre %}: {{ fel.establecimiento.nombre }}{% endif %}</div>{% endif %}
      </td>
      <td style="vertical-align:top; text-align:right">
        <h2>{{ fel.title }}</h2>
        {%- if fel.envio %}
        <div>{{ _("Serie") }} <b>{{ fel.envio.serie }}</b> &middot; {{ _("Número") }} <b>{{ fel.envio.numero }}</b></div>
        <div class="uuid">{{ _("Autorización") }}: {{ fel.envio.uuid }}</div>
        <div>{{ _("Certificación") }}: {{ fel.fecha_certificacion }}</div>
        {%- endif %}
        <div>{{ _("Emisión") }}: {{ frappe.utils.format_date(doc.posting_date) }}</div>
        {%- if fel.access_number %}<div>{{ _("Número de acceso") }}: {{ fel.access_number }}</div>{% endif %}
        {%- if fel.tipo_cambio %}<div>{{ _("Moneda") }} {{ doc.currency }} &middot; {{ _("Tipo de cambio") }} {{ fel.tipo_cambio }}</div>{% endif %}
      </td>
    </tr>
  </table>

  {%- if fel.anulado %}
  <div class="void">{{ _("DOCUMENTO ANULADO") }}{% if fel.anulado.fecha %} &middot; {{ fel.anulado.fecha }}{% endif %}
    {%- if fel.anulado.motivo %}<div style="font-size:12px; font-weight:normal">{{ _("Motivo") }}: {{ fel.anulado.motivo }}</div>{% endif %}
  </div>
  {%- elif fel.demo %}
  <div class="warn">{{ _("DOCUMENTO DE PRUEBA (modo Demo): no fue enviado a ningún certificador ni a SAT y no tiene validez fiscal.") }}</div>
  {%- elif fel.contingency and not fel.certified %}
  <div class="warn">{{ _("DOCUMENTO EMITIDO EN CONTINGENCIA: pendiente de certificación ante SAT.") }}</div>
  {%- elif not fel.certified %}
  <div class="warn">{{ _("DOCUMENTO NO CERTIFICADO: no tiene validez como DTE.") }}</div>
  {%- endif %}

  <div class="box">
    <div>{{ _("Cliente") }}: <b>{{ doc.nombre_segun_sat or doc.customer_name }}</b></div>
    <div>{{ _("NIT / CUI") }}: {{ doc.nit_face_customer or doc.tax_id or "CF" }}</div>
    {%- if doc.address_display %}<div>{{ _("Dirección") }}: {{ doc.address_display | striptags }}</div>{% endif %}
  </div>

  <table class="lines" style="margin-top:8px">
    <thead>
      <tr><th class="num">{{ _("Cant.") }}</th><th>{{ _("Descripción") }}</th><th class="num">{{ _("Precio unitario") }}</th><th class="num">{{ _("Descuento") }}</th><th class="num">{{ _("Total") }}</th></tr>
    </thead>
    <tbody>
      {%- for item in doc.items %}
      <tr>
        <td class="num">{{ item.get_formatted("qty") }}</td>
        <td>{{ item.item_name }}</td>
        <td class="num">{{ item.get_formatted("rate") }}</td>
        <td class="num">{{ frappe.utils.fmt_money((item.discount_amount or 0) * item.qty, currency=doc.currency) }}</td>
        <td class="num">{{ item.get_formatted("amount") }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  {%- if fel.abonos %}
  <table class="lines" style="margin-top:8px; width:60%">
    <thead><tr><th>{{ _("Abono") }}</th><th>{{ _("Vencimiento") }}</th><th class="num">{{ _("Monto") }}</th></tr></thead>
    <tbody>
      {%- for abono in fel.abonos %}
      <tr><td>{{ abono.numero }}</td><td>{{ abono.vencimiento }}</td><td class="num">{{ frappe.utils.fmt_money(abono.monto, currency=doc.currency) }}</td></tr>
      {%- endfor %}
    </tbody>
  </table>
  {%- endif %}

  <table style="margin-top:8px">
    <tr>
      <td style="width:62%; vertical-align:top">
        {%- for tax in doc.taxes %}{% if tax.tax_amount %}
        <div>{{ tax.description or tax.account_head }} ({{ _("incluido") }}): {{ tax.get_formatted("tax_amount") }}</div>
        {%- endif %}{% endfor %}
        <div style="margin-top:4px"><b>{{ currency_in_words(doc.grand_total, doc.currency) }}</b></div>
        {%- for frase in fel.frases %}<div><i>{{ frase }}</i></div>{% endfor %}
      </td>
      <td style="vertical-align:top; text-align:right">
        <div style="font-size:14px">{{ _("TOTAL") }}: <b>{{ doc.get_formatted("grand_total") }}</b></div>
        {%- if fel.qr and not fel.demo and not fel.anulado %}
        <div class="qr" style="margin-top:6px">{{ fel.qr }}</div>
        <div class="muted">{{ _("Escanee para verificar el documento") }}</div>
        {%- endif %}
      </td>
    </tr>
  </table>

  {%- if fel.certifier and not fel.demo %}
  <div class="muted" style="margin-top:10px; text-align:center">{{ _("Certificador") }}: {{ fel.certifier.razon_social }} &middot; NIT {{ fel.certifier.nit }}</div>
  {%- endif %}
</div>
